As for the R code, you could use the following function to check whether a password contains at least one special character and does not contain a common pattern:
```R
# Function to check password validity
check_password <- function(password) {
  # List of recommended special characters
  special_chars <- c("!", "@", "#", "$", "%", "^", "&", "*", "(", ")", "-", "_", "=", "+", "[", "]", "{", "}", ";", ":", "'", "\"", ",", ".", "<", ">", "/", "?", "|", "`", "~")

  # Check if password contains at least one special character
  if (!grepl("[[:punct:]]", password)) {
    return(FALSE)
  }

  # Check if password is a permutation of a common pattern
  patterns <- c("123", "234", "345", "456", "567", "678", "789", "890", "qwerty", "asdfgh", "zxcvbn", "qazwsx", "zaq12wsx", "xsw23edc", "cde34rfv", "vfr45tgb", "bgt56yhn", "nhy67ujm", "mju78ikl", "poi98uyt", "lkj87uhg", "mnbvcxz", "poiuytrewq", "lkjhgfdsa", "0987654321")
  for (pattern in patterns) {
    if (all(strsplit(password, "")[[1]][order(match(strsplit(password, "")[[1]], strsplit(pattern, "")[[1]]))] == strsplit(pattern, "")[[1]])) {
      return(FALSE)
    }
  }

  return(TRUE)
}
```
