func buildPositivePhrase(_ phrase: String) -> String {
    let positiveWords = ["happy", "joy", "love", "hope", "peace", "grateful", "thankful", "meaningful"]
    let grammaticallyValidPhrases = phrase.reversed().filter {
        let wordSet = Set(positiveWords)
        let words = $0.split(separator: " ")
        return words.all { !wordSet.contains($0) || $0.isEmpty }
